const languageKey = "undokai-language";
let language = "en";
try {
  if (localStorage.getItem(languageKey) === "ja") language = "ja";
} catch {
  // The toggle works during the visit even when storage is unavailable.
}

function translate(source, values = {}) {
  const copy = language === "ja" ? (japaneseCopy[source] ?? source) : source;
  return copy.replace(/\{(\w+)\}/g, (token, key) => Object.hasOwn(values, key) ? translate(String(values[key])) : token);
}

const languageListeners = [];
function onLanguageChange(listener) {
  languageListeners.push(listener);
}

const staticCopy = [];
const formattedElements = new Set();
const normalizeCopy = (text) => text.trim().replace(/\s+/g, " ");
const formattedCopySelector = ".race-facts li, .rule-list li > span, #dsc-title > span";

document.querySelectorAll(formattedCopySelector).forEach((element) => {
  const japanese = japaneseFormatted[normalizeCopy(element.textContent)];
  if (!japanese) return;
  const english = element.innerHTML;
  formattedElements.add(element);
  staticCopy.push(() => { element.innerHTML = language === "ja" ? japanese : english; });
});

const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
  const node = walker.currentNode;
  if (node.parentElement.closest('script, style, svg, [data-language], [lang="en"]:not(html)')) continue;
  const richParent = node.parentElement.closest(formattedCopySelector);
  if (formattedElements.has(richParent)) continue;
  const english = node.data;
  const key = normalizeCopy(english);
  if (!Object.hasOwn(japaneseCopy, key)) continue;
  staticCopy.push(() => {
    node.data = language === "en" ? english : english.match(/^\s*/)[0] + translate(key) + english.match(/\s*$/)[0];
  });
}

for (const attribute of ["aria-label", "alt", "content"]) {
  const selector = attribute === "content" ? 'meta[name="description"]' : `[${attribute}]`;
  document.querySelectorAll(selector).forEach((element) => {
    const english = element.getAttribute(attribute);
    if (Object.hasOwn(japaneseCopy, english)) {
      staticCopy.push(() => element.setAttribute(attribute, translate(english)));
    }
  });
}

const languageToggle = document.querySelector(".language-toggle");
const languageButtons = [...languageToggle.querySelectorAll("button")];
function applyLanguage() {
  document.documentElement.lang = language;
  staticCopy.forEach((apply) => apply());
  languageButtons.forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.language === language)));
  languageListeners.forEach((listener) => listener());
}

languageButtons.forEach((button) => button.addEventListener("click", () => {
  if (language === button.dataset.language) return;
  language = button.dataset.language;
  try { localStorage.setItem(languageKey, language); } catch { /* Storage is optional. */ }
  applyLanguage();
}));
applyLanguage();
languageToggle.hidden = false;
